"""Load the shared machine contract (contracts/, generated by contracts/build.mjs).

The backend validates request bodies against the canonical JSON Schema instead of keeping a second
DTO set; response shapes are verified against the same schema in tests.
"""
from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path
from typing import Any

from jsonschema import Draft202012Validator, FormatChecker
from referencing import Registry, Resource

from app.config import get_settings

CONTRACT_VERSION = '1.1.0'
SCHEMA_VERSION = 1
RULESET_STATUS = 'development'
MAP_ID = 'standard'
INITIAL_FEN = '9/pbkpbkpbk/kpbkpbkpb/9/9/9/BPKBPKBPK/KBPKBPKBP/9'
# GameConfig constants are `const` in contracts/schemas (dev-v1).
GAME_LIMITS = {'budget_ms': 60000, 'init_ms': 10000, 'grace_ms': 50, 'hard_timeout_extra_ms': 1000, 'max_turns': 300}


def contracts_dir() -> Path:
    return Path(get_settings().contracts_dir)


def read_json(relative: str) -> Any:
    return json.loads((contracts_dir() / relative).read_text(encoding='utf-8'))


@lru_cache
def _registry() -> Registry:
    resources = []
    for path in (contracts_dir() / 'schemas').glob('*.json'):
        resources.append((path.as_uri(), Resource.from_contents(json.loads(path.read_text(encoding='utf-8')))))
    return Registry().with_resources(resources)


@lru_cache
def validator(definition: str) -> Draft202012Validator:
    common = (contracts_dir() / 'schemas' / 'common.schema.json').as_uri()
    return Draft202012Validator({'$ref': f'{common}#/$defs/{definition}'}, registry=_registry(), format_checker=FormatChecker())


def errors(definition: str, data: Any) -> list[dict[str, str]]:
    found = []
    for error in sorted(validator(definition).iter_errors(data), key=lambda e: list(e.absolute_path)):
        reason = 'Giá trị không hợp lệ' if definition in ('Login', 'Register') else error.message[:300]
        found.append({'field': '/' + '/'.join(str(p) for p in error.absolute_path), 'reason': reason})
    return found


@lru_cache
def operations() -> list[dict[str, Any]]:
    return read_json('operations.json')


def check_version() -> None:
    """Fail fast when the checked-out contract is not the one this code implements."""
    version = read_json('version.json')
    expected = {'contract_version': CONTRACT_VERSION, 'ruleset_id': 'dev-v1', 'ruleset_status': RULESET_STATUS,
                'schema_version': SCHEMA_VERSION}
    for key, value in expected.items():
        if version.get(key) != value:
            raise RuntimeError(f'contracts/version.json {key}={version.get(key)!r}, backend implements {value!r}')
